SINA_SMART["genetics1-transcription"] = {"lecture":"genetics1-transcription","title":"DNA transcription","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"genetics1-transcription:e0","text":"Transcription: DNA → primary RNA transcript in the nucleus.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-transcription:e1","text":"Tm = 50% of pairs separated; rises with GC, length, cations; hyperchromic effect at 260 nm.","topic":"DNA stability, denaturation and Tm","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-transcription:e2","text":"Template (antisense) read 3′→5′; RNA made 5′→3′; RNA = sense strand with U.","topic":"Template strand and RNA","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-transcription:e3","text":"Pol I: 28S, 18S, 5.8S rRNA (nucleolus). Pol II: mRNA (CTD). Pol III: tRNA, 5S rRNA.","topic":"RNA polymerases and RNA types","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-transcription:e4","text":"CTD: YSPTSPS repeats (52 in humans); phosphorylation drives the transcription cycle.","topic":"RNA polymerases and RNA types","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-transcription:e5","text":"TATA box ~ −25/−30 (TBP); Inr at +1; DPE downstream; GC box (Sp1); CAAT box.","topic":"Promoters, factors and the three phases","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-transcription:e6","text":"TFIID first (TBP), TFIIB positions Pol II, TFIIH helicase + CTD kinase.","topic":"Promoters, factors and the three phases","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-transcription:e7","text":"Activators: enhancers, HATs. Repressors: silencers, HDACs.","topic":"Promoters, factors and the three phases","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-transcription:e8","text":"Motifs: helix-loop-helix, zinc finger, leucine zipper.","topic":"Promoters, factors and the three phases","sec":4,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-transcription:e9","text":"Termination: AAUAAA, CPSF + CstF cleavage, poly(A) polymerase, XRN2 torpedo.","topic":"Promoters, factors and the three phases","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"oco9m1":"a","duhw6s":"a","1o5km3n":"a","z8yptb":"a","nobbkp":"a","1y0se9k":"a","s2tb2s":"a","jdift1":"a","12vjmhr":"a","s0fs7a":"a","1eimxin":"a","10rkkkt":"a","ku3ias":"a","10rtmgd":"a","14o164g":"a","dm7ghc":"a"},"mapCounts":{"verified":0,"auto":16,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"genetics1-transcription:e0":{"s":0,"u":["Transcription: DNA → primary RNA transcript in the nucleus.","Transcription (in the nucleus) uses RNA polymerase to copy a DNA template into a primary transcript , which is then processed; translation follows in the cytoplasm.","Requirements: DNA template, RNA polymerase, transcription factors, NTPs , Mg²⁺."],"dp":[]},"genetics1-transcription:e1":{"s":1,"u":["Tm = 50% of pairs separated; rises with GC, length, cations; hyperchromic effect at 260 nm.","The melting temperature (Tm) is where 50% of base pairs are separated; Tm rises with GC content, length and cations .","Single-stranded DNA absorbs more UV at 260 nm ( hyperchromic effect )."],"dp":[]},"genetics1-transcription:e2":{"s":2,"u":["Template (antisense) read 3′→5′; RNA made 5′→3′; RNA = sense strand with U.","The template (antisense) strand is read 3′→5′ ; RNA is made 5′→3′ , adding to the 3′-OH, and is complementary to the template, so it has the same sequence as the sense (coding, non-template) strand with U for T."],"dp":[]},"genetics1-transcription:e3":{"s":3,"u":["Pol I: 28S, 18S, 5.8S rRNA (nucleolus). Pol II: mRNA (CTD). Pol III: tRNA, 5S rRNA.","Pol I (nucleolus): 47S pre-rRNA → 28S, 18S, 5.8S rRNA (genes on acrocentric chromosomes 13, 14, 15, 21, 22: nucleolar organiser regions).","Pol III : tRNA, 5S rRNA , U6 snRNA, 7SL, 7SK (internal A and B boxes; TFIIIA/B/C; repressor Maf1)."],"dp":[]},"genetics1-transcription:e4":{"s":3,"u":["CTD: YSPTSPS repeats (52 in humans); phosphorylation drives the transcription cycle.","Pol II (nucleoplasm): mRNA and some regulatory RNAs (snRNA, lncRNA); couples transcription with capping, splicing and polyadenylation via its C-terminal domain (CTD) : repeats of YSPTSPS (52 in humans) on the largest subunit RPB1, whose serine phosphorylation controls initiation → elongation → termination; Pol I and III lack it."],"dp":[]},"genetics1-transcription:e5":{"s":4,"u":["TATA box ~ −25/−30 (TBP); Inr at +1; DPE downstream; GC box (Sp1); CAAT box.","Promoter elements : TATA box (~25-30 bp upstream of +1; bound by TBP), Inr (spans +1), DPE (+28 to +32, in TATA-less promoters), CAAT box (CTF; strong genes), GC box (Sp1).","Initiation : TBP binds and bends the TATA box → TFIIB → Pol II-TFIIF → TFIIE → TFIIH completes the pre-initiation complex ; TFIIH helicase unwinds DNA (open complex); CTD phosphorylation triggers promoter clearance ."],"dp":[]},"genetics1-transcription:e6":{"s":4,"u":["TFIID first (TBP), TFIIB positions Pol II, TFIIH helicase + CTD kinase.","General transcription factors : TFIID (TBP + 13 TAFs; binds first), TFIIA (stabilises), TFIIB (positions Pol II at +1), TFIIF (escorts Pol II), TFIIE (recruits TFIIH), TFIIH (helicase + CTD kinase).","Initiation : TBP binds and bends the TATA box → TFIIB → Pol II-TFIIF → TFIIE → TFIIH completes the pre-initiation complex ; TFIIH helicase unwinds DNA (open complex); CTD phosphorylation triggers promoter clearance ."],"dp":[{"h":"Why TFIIH is the switch from start to go","t":"TFIIH does two jobs at the right moment: its helicase opens the DNA so the template is exposed, and its kinase phosphorylates the Pol II tail. The phosphorylated CTD loosens the polymerase's grip on the initiation factors so it can leave the promoter, and becomes a landing pad for the enzymes that cap and splice the new RNA. Source: the lecture's initiation phase slides."}]},"genetics1-transcription:e7":{"s":4,"u":["Activators: enhancers, HATs. Repressors: silencers, HDACs.","Activators bind enhancers, recruit coactivators and HATs (open chromatin); repressors bind silencers, recruit corepressors and HDACs; both act at a distance by DNA looping."],"dp":[]},"genetics1-transcription:e8":{"s":4,"u":["Motifs: helix-loop-helix, zinc finger, leucine zipper.","DNA-binding motifs: helix-loop-helix (MyoD), zinc finger (steroid receptors), leucine zipper (Fos/Jun, AP-1)."],"dp":[]},"genetics1-transcription:e9":{"s":4,"u":["Termination: AAUAAA, CPSF + CstF cleavage, poly(A) polymerase, XRN2 torpedo.","Termination (not sequence-defined, unlike bacteria): the AAUAAA signal is bound by CPSF and CstF , the RNA is cut, poly(A) polymerase adds the tail, and the XRN2 'torpedo' exonuclease degrades the remaining RNA until Pol II falls off."],"dp":[{"h":"Why eukaryotic termination is 'torpedo'-driven","t":"Bacterial genes end with sequences that directly stop the polymerase. In eukaryotes, Pol II keeps going past the polyadenylation site; once the RNA is cut there, an exonuclease (XRN2) chews the leftover RNA still attached to Pol II and catches up with it, knocking it off. Termination is thus linked to making the poly(A) tail. Source: the lecture's termination slide."}]}},"meta":{"oco9m1":{"a":"recall","vg":"genetics1-transcription:e1/recall/1"},"duhw6s":{"a":"recall","vg":"genetics1-transcription:e1/recall/2"},"1o5km3n":{"a":"recall","vg":"genetics1-transcription:e2/recall/1"},"z8yptb":{"a":"recall","vg":"genetics1-transcription:e2/recall/1"},"nobbkp":{"a":"recall","vg":"genetics1-transcription:e3/recall/1"},"1y0se9k":{"a":"recall","vg":"genetics1-transcription:e3/recall/1"},"s2tb2s":{"a":"recall","vg":"genetics1-transcription:e4/recall/1"},"jdift1":{"a":"recall","vg":"genetics1-transcription:e5/recall/1"},"12vjmhr":{"a":"recall","vg":"genetics1-transcription:e6/recall/1"},"s0fs7a":{"a":"recall","vg":"genetics1-transcription:e6/recall/2"},"1eimxin":{"a":"recall","vg":"genetics1-transcription:e6/recall/3"},"10rkkkt":{"a":"recall","vg":"genetics1-transcription:e7/recall/1"},"ku3ias":{"a":"recall","vg":"genetics1-transcription:e8/recall/1"},"10rtmgd":{"a":"recall","vg":"genetics1-transcription:e9/recall/1"},"14o164g":{"a":"recall","vg":"genetics1-transcription:e9/recall/2"},"dm7ghc":{"a":"recall","vg":"genetics1-transcription:e3/recall/2"}},"explRev":"368432ef447b"};
